import { createHash } from 'node:crypto';
import { createRandom } from './index-build-corpus';

/**
 * A fixed conversation corpus for the thread-embedding benchmark: `threads`
 * threads of alternating user/assistant messages, generated by the same PRNG
 * as the index-build corpus. The same seed and shape always produce the same
 * text, so runs compare only when their SHA-256 matches.
 */
export interface ThreadMessageCorpus {
  readonly bytes: number;
  readonly messagesPerThread: number;
  readonly seed: number;
  readonly sha256: string;
  readonly threads: readonly {
    readonly messages: readonly { readonly role: 'assistant' | 'user'; readonly text: string }[];
    readonly title: string;
  }[];
}

const WORDS = [
  'adapter',
  'branch',
  'cache',
  'commit',
  'config',
  'deploy',
  'embedding',
  'error',
  'folder',
  'handler',
  'index',
  'latency',
  'memory',
  'migration',
  'model',
  'parser',
  'query',
  'release',
  'renderer',
  'request',
  'schema',
  'search',
  'session',
  'stream',
  'test',
  'thread',
  'token',
  'tool',
  'vector',
  'worker',
];
const VERBS = ['add', 'check', 'explain', 'fix', 'measure', 'move', 'rename', 'review', 'split'];

function sentence(random: () => number): string {
  const word = (): string => WORDS[Math.floor(random() * WORDS.length)] ?? 'thread';
  const verb = VERBS[Math.floor(random() * VERBS.length)] ?? 'check';
  const length = 6 + Math.floor(random() * 10);
  const words = [verb, 'the', ...Array.from({ length }, word)];
  return `${words.join(' ')}.`;
}

/** Messages of 2-6 sentences, about the length of an ordinary chat turn. */
export function createThreadMessageCorpus(options: {
  readonly messagesPerThread: number;
  readonly seed: number;
  readonly threads: number;
}): ThreadMessageCorpus {
  const random = createRandom(options.seed);
  const digest = createHash('sha256');
  let bytes = 0;
  const threads = Array.from({ length: options.threads }, (_, threadIndex) => {
    const messages = Array.from({ length: options.messagesPerThread }, (_, index) => {
      const sentences = 2 + Math.floor(random() * 5);
      const text = Array.from({ length: sentences }, () => sentence(random)).join(' ');
      const role = index % 2 === 0 ? ('user' as const) : ('assistant' as const);
      digest.update(`${threadIndex}:${index}:${role}:${text}\n`);
      bytes += Buffer.byteLength(text);
      return { role, text };
    });
    return { messages, title: `Benchmark thread ${threadIndex + 1}` };
  });
  return {
    bytes,
    messagesPerThread: options.messagesPerThread,
    seed: options.seed,
    sha256: digest.digest('hex'),
    threads,
  };
}
